import{_ as t,o as r,c as s,a2 as n}from"./chunks/framework.CqdVOxXJ.js";const p=JSON.parse('{"title":"10. Workshop operations: board, calendar, customers, backjobs & contractors","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/10-workshop-operations-board-calendar-backjobs-contractors.md","filePath":"chapters/10-workshop-operations-board-calendar-backjobs-contractors.md","lastUpdated":null}'),e={name:"chapters/10-workshop-operations-board-calendar-backjobs-contractors.md"};function a(i,o,g,c,l,d){return r(),s("div",null,[...o[0]||(o[0]=[n('<h1 id="_10-workshop-operations-board-calendar-customers-backjobs-contractors" tabindex="-1">10. Workshop operations: board, calendar, customers, backjobs &amp; contractors <a class="header-anchor" href="#_10-workshop-operations-board-calendar-customers-backjobs-contractors" aria-label="Permalink to &quot;10. Workshop operations: board, calendar, customers, backjobs &amp; contractors&quot;">​</a></h1><p><strong>For:</strong> Shop Owner · <strong>Hub:</strong> Workshop</p><p>The pages in this chapter help you run the floor across all jobs at once instead of one job at a time.</p><h2 id="_10-1-shop-board-workshop-board" tabindex="-1">10.1 Shop board (<code>/workshop/board</code>) <a class="header-anchor" href="#_10-1-shop-board-workshop-board" aria-label="Permalink to &quot;10.1 Shop board (`/workshop/board`)&quot;">​</a></h2><p>The Kanban view of every car in play. Each card shows the plate, a subtitle (type, category), the customer, checklist progress, promised date and any amount the customer still owes.</p><table tabindex="0"><thead><tr><th>Lane</th><th>Statuses in it</th></tr></thead><tbody><tr><td><strong>New</strong></td><td>New inquiry, Booked</td></tr><tr><td><strong>Quote / LOA</strong></td><td>For canvass, Quoted, Waiting for LOA, Authorized</td></tr><tr><td><strong>Under repair</strong></td><td>Under repair</td></tr><tr><td><strong>Parts &amp; QC</strong></td><td>Waiting for parts, Quality check</td></tr><tr><td><strong>On hold</strong></td><td>On hold</td></tr><tr><td><strong>Ready</strong></td><td>Ready for pickup (in play for 90 days)</td></tr></tbody></table><p><strong>Filters</strong></p><ul><li>Scope: <strong>Mine</strong>, <strong>All open</strong>, <strong>All</strong>.</li><li>Type: <strong>Retail</strong>, <strong>Insurance</strong>, <strong>Fleet</strong>.</li><li><strong>Lane</strong> (or <strong>All lanes</strong>).</li><li><strong>Promised</strong>: <strong>Any date</strong>, <strong>Due today</strong>, <strong>Overdue</strong>.</li><li><strong>Stuck</strong>: <strong>Any</strong>, <strong>Waiting LOA</strong>, <strong>Waiting parts</strong>, <strong>Unpaid</strong>.</li><li><strong>Work category</strong>.</li></ul><p>Switch between <strong>Columns</strong> (Kanban) and <strong>List</strong> (sortable table: Plate, Customer, Lane, Status, Type, Category, Promised, Balance). Jobs that match a search but are off the board (released, closed) show under <strong>Also found (off the board)</strong>.</p><p><strong>Morning routine:</strong> filter <strong>Promised: Due today</strong> and <strong>Overdue</strong>, then <strong>Stuck: Unpaid</strong> on the Ready lane — those cars must not leave until paid.</p><p>The <strong>Dashboard</strong> (<code>/workshop</code>) complements the board with <strong>Due today</strong>, <strong>New web &amp; Messenger inquiries</strong> (with <strong>Confirm booking</strong>), <strong>Ready, but customer still owes</strong>, <strong>Today&#39;s appointments</strong> (Confirmed / In shop / Waiting), <strong>Announcements</strong>, and counts by status, type and channel.</p><div class="info custom-block"><p class="custom-block-title">📷 Screenshot placeholder</p><p><code>/screenshots/10-workshop-operations-board-calendar-backjobs-contractors/01-shop-board.png</code> — Shop board columns view with filters.</p></div><h2 id="_10-2-appointment-promised-date-calendar-workshop-calendar" tabindex="-1">10.2 Appointment &amp; promised-date calendar (<code>/workshop/calendar</code>) <a class="header-anchor" href="#_10-2-appointment-promised-date-calendar-workshop-calendar" aria-label="Permalink to &quot;10.2 Appointment &amp; promised-date calendar (`/workshop/calendar`)&quot;">​</a></h2><ol><li>Open <strong>Workshop › Calendar</strong>. The week is shown; pick a <strong>Day</strong>.</li><li>The selected day lists every job <strong>promised</strong> for that day (plate, customer, type and status).</li><li><strong>No date yet</strong> lists open jobs without a promised date — give each one a date.</li><li><strong>Book this day</strong> starts a new job with that promised date.</li></ol><p><strong>Setting the date and appointment on a job:</strong> job <strong>Overview</strong> → <strong>Promised</strong> line → set <strong>Date</strong>, <strong>Time window</strong> and appointment <strong>Status</strong> (<strong>Confirmed</strong>, <strong>In shop</strong>, <strong>Waiting</strong>) → <strong>Save</strong>. <strong>Clear chip</strong> removes the appointment.</p><h2 id="_10-3-customers-vehicle-service-history" tabindex="-1">10.3 Customers &amp; vehicle service history <a class="header-anchor" href="#_10-3-customers-vehicle-service-history" aria-label="Permalink to &quot;10.3 Customers &amp; vehicle service history&quot;">​</a></h2><h3 id="customers-workshop-customers" tabindex="-1">Customers (<code>/workshop/customers</code>) <a class="header-anchor" href="#customers-workshop-customers" aria-label="Permalink to &quot;Customers (`/workshop/customers`)&quot;">​</a></h3><p>The list shows each customer with <strong>Cars</strong>, <strong>Last visit</strong>, <strong>Total spent</strong> and <strong>Open jobs</strong>. Use <strong>New customer</strong> or open a row.</p><p>On the customer page (<code>/workshop/customers/:id</code>):</p><ul><li><strong>Customer</strong> details: Name, Mobile, Email, Category (Person, Company, Government), TIN, Credit terms, Billing address, Notes — <strong>Edit</strong> to change.</li><li><strong>Cars</strong> — every vehicle, with last visit; <strong>Add car</strong>.</li><li><strong>Open jobs</strong> and <strong>Service history</strong> (date, plate, work done, amount).</li><li><strong>New job for them</strong> starts a job with the customer filled in.</li></ul><h3 id="vehicles-workshop-vehicles-id" tabindex="-1">Vehicles (<code>/workshop/vehicles/:id</code>) <a class="header-anchor" href="#vehicles-workshop-vehicles-id" aria-label="Permalink to &quot;Vehicles (`/workshop/vehicles/:id`)&quot;">​</a></h3><ul><li><strong>Car</strong> details: Plate (fixed once on file), Make, Model, Year, Color, VIN, Notes.</li><li><strong>Owner</strong>, <strong>Open jobs</strong> and <strong>Service history</strong> for this car across all owners.</li><li><strong>Move to new owner</strong> when a car is sold. The car&#39;s service history stays with the car.</li></ul><h2 id="_10-4-backjob-monitor-workshop-backjobs" tabindex="-1">10.4 Backjob Monitor (<code>/workshop/backjobs</code>) <a class="header-anchor" href="#_10-4-backjob-monitor-workshop-backjobs" aria-label="Permalink to &quot;10.4 Backjob Monitor (`/workshop/backjobs`)&quot;">​</a></h2><p>A backjob is a car that comes back for the same work (a warranty return or comeback).</p><h3 id="log-a-backjob-on-the-original-job" tabindex="-1">Log a backjob on the original job <a class="header-anchor" href="#log-a-backjob-on-the-original-job" aria-label="Permalink to &quot;Log a backjob on the original job&quot;">​</a></h3><ol><li>Open the <strong>original</strong> job (the one being complained about). On <strong>Overview</strong>, card <strong>Backjobs</strong>, press <strong>Log backjob</strong>.</li><li>Fill <strong>Complaint</strong>, <strong>Date returned</strong>, and who is <strong>Responsible</strong> — pick <strong>Staff</strong> (a technician) or <strong>Contractor</strong> (name).</li><li>Tick <strong>Under warranty</strong> if the shop covers it. Add a <strong>Note</strong>.</li><li>Save. Track its <strong>Status</strong>: <strong>Open</strong>, <strong>Fixed</strong> or <strong>Not a backjob</strong>.</li><li><strong>Confirm / change responsible</strong> once the cause is clear.</li><li><strong>Add cost</strong> for every peso spent fixing it: <strong>Category</strong>, <strong>Amount</strong>, <strong>Date</strong>, <strong>Payee</strong> (required for contractor costs), <strong>Note</strong>, <strong>Paid from</strong>. Costs are recorded as shop expenses. <strong>Save warranty note</strong> for the customer-facing warranty remark.</li></ol><p>Backjobs do not change technician pay. They can feed KPI scorecards as a hint (<a href="/rakkii-cars-guide/chapters/11-hr-payroll-kiosk-announcements-documents">Chapter 11</a>).</p><h3 id="the-monitor" tabindex="-1">The monitor <a class="header-anchor" href="#the-monitor" aria-label="Permalink to &quot;The monitor&quot;">​</a></h3><ul><li><strong>By responsible</strong> (this month): <strong>Who</strong>, <strong>Kind</strong> (staff or contractor), number of <strong>Backjobs</strong>, total <strong>Cost</strong>.</li><li><strong>Still open</strong> (any month): <strong>Returned</strong>, <strong>Job</strong>, <strong>Plate</strong>, <strong>Customer</strong>, <strong>Complaint</strong>, <strong>Responsible</strong>, <strong>Warranty</strong>, <strong>Cost</strong>. Items stay until fixed or cleared.</li></ul><h2 id="_10-5-contractor-monitor-workshop-contractors" tabindex="-1">10.5 Contractor Monitor (<code>/workshop/contractors</code>) <a class="header-anchor" href="#_10-5-contractor-monitor-workshop-contractors" aria-label="Permalink to &quot;10.5 Contractor Monitor (`/workshop/contractors`)&quot;">​</a></h2><p>Sublet work (for example upholstery, glass or engine machining) is tracked on the job and monitored here.</p><h3 id="on-the-job-job-order-—-contractors-work-tab" tabindex="-1">On the job: Job Order — Contractors (Work tab) <a class="header-anchor" href="#on-the-job-job-order-—-contractors-work-tab" aria-label="Permalink to &quot;On the job: Job Order — Contractors (Work tab)&quot;">​</a></h3><ol><li>Press <strong>Add contractor</strong>.</li><li>Fill <strong>Contractor</strong>, <strong>Scope</strong> (prefilled from the job&#39;s work category if the shop setting is on), <strong>Status</strong>, <strong>Date start</strong>, <strong>Commitment date</strong>, <strong>Completion date</strong>, <strong>Labour</strong> (agreed amount) and <strong>Note</strong>.</li><li>Save. The line shows days, labour, <strong>Adv. paid</strong> and <strong>Balance</strong>.</li><li>Move it with <strong>Mark ON-GOING</strong> and <strong>Mark COMPLETED</strong>. If the shop requires a contractor signature, completing without one needs an owner/admin reason (<strong>Complete anyway</strong>). Upload a <strong>Signature photo</strong> or type the <strong>Contractor signature</strong> name.</li><li>Pay the contractor with <strong>Adv. paid</strong> (advance) or <strong>Payment</strong>: <strong>Date</strong>, <strong>Paid from</strong>, <strong>Note</strong>. Each payout can be voided.</li><li><strong>Cancel line</strong> if the sublet is called off.</li></ol><p>Statuses: <strong>OPEN</strong>, <strong>ON-GOING</strong>, <strong>COMPLETED</strong>, <strong>CANCELLED</strong>. Technicians see the list read-only.</p><h3 id="the-monitor-1" tabindex="-1">The monitor <a class="header-anchor" href="#the-monitor-1" aria-label="Permalink to &quot;The monitor&quot;">​</a></h3><ul><li>Filters: <strong>Status</strong> (Open and ON-GOING, ON-GOING, COMPLETED, CANCELLED, All), <strong>Contractor</strong>, <strong>Overdue commitment dates only</strong>.</li><li>Columns: <strong>Job</strong>, <strong>Plate</strong>, <strong>Contractor</strong>, <strong>Scope</strong>, <strong>Status</strong>, <strong>Commitment date</strong>, <strong>Days</strong>, <strong>Labour</strong>, <strong>Adv. paid</strong>, <strong>Balance</strong>.</li><li>Badges: <strong>Overdue</strong>, <strong>Due today</strong>, <strong>Soon</strong> (warning days set in <strong>Shop settings › Workshop rules › Contractors</strong>).</li></ul><div class="info custom-block"><p class="custom-block-title">📷 Screenshot placeholder</p><p><code>/screenshots/10-workshop-operations-board-calendar-backjobs-contractors/02-contractor-monitor.png</code> — Contractor jobs monitor with overdue filter.</p></div>',37)])])}const b=t(e,[["render",a]]);export{p as __pageData,b as default};
